import json
from fractions import Fraction

# Polynomials in (h, f_1, f_2), with exact rational coefficients.
def add(p, q):
    result = dict(p)
    for monomial, coefficient in q.items():
        result[monomial] = result.get(monomial, Fraction(0)) + coefficient
    return {m: c for m, c in result.items() if c}

def multiply(p, q):
    result = {}
    for m, c in p.items():
        for n, d in q.items():
            exponent = tuple(a + b for a, b in zip(m, n))
            result[exponent] = result.get(exponent, Fraction(0)) + c * d
    return {m: c for m, c in result.items() if c}

def restrict_h(p, value):
    result = {}
    for (h_power, f1_power, f2_power), coefficient in p.items():
        monomial = (0, f1_power, f2_power)
        term = coefficient * value ** h_power
        result[monomial] = result.get(monomial, Fraction(0)) + term
    return {m: c for m, c in result.items() if c}

def format_polynomial(p):
    pieces = []
    names = ("h", "f_1", "f_2")
    for powers, coefficient in sorted(p.items()):
        factors = [
            name if power == 1 else f"{name}^{power}"
            for name, power in zip(names, powers) if power
        ]
        magnitude = abs(coefficient)
        if magnitude != 1 or not factors:
            factors.insert(0, str(magnitude))
        term = "*".join(factors)
        if not pieces:
            pieces.append(("-" if coefficient < 0 else "") + term)
        else:
            pieces.append((" - " if coefficient < 0 else " + ") + term)
    return "".join(pieces) or "0"

one = {(0, 0, 0): Fraction(1)}
h = {(1, 0, 0): Fraction(1)}
f1 = {(0, 1, 0): Fraction(1)}
f2 = {(0, 0, 1): Fraction(1)}

one_minus_h = add(one, {m: -c for m, c in h.items()})
g = add(multiply(one_minus_h, f1), multiply(h, f2))
on_A = restrict_h(g, Fraction(0))
on_B = restrict_h(g, Fraction(1))

# Complete separation supplies a continuous h with h|A=0 and h|B=1.
# The constructed polynomial uses only sums and products of continuous functions.
verified = on_A == f1 and on_B == f2

if not verified:
    print(json.dumps({"final_answer": "UNSUPPORTED", "evidence": {}}))
else:
    formula = format_polynomial(g)
    print(json.dumps({
        "final_answer": (
            f"Yes. Complete separation supplies a continuous h: X -> [0,1] "
            f"with h=0 on A and h=1 on B. Define g={formula}. "
            f"This is continuous because sums and products of continuous "
            f"real-valued functions are continuous. Substitution gives "
            f"g={format_polynomial(on_A)} on A and "
            f"g={format_polynomial(on_B)} on B."
        ),
        "evidence": {
            "constructed_polynomial": formula,
            "h=0": format_polynomial(on_A),
            "h=1": format_polynomial(on_B),
            "both_restrictions_verified": verified
        }
    }))
